def transform(grid):
    # Find all non-zero positions
    positions = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0:
                positions.add((i, j))

    # Find marker color
    marker = None
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0:
                marker = grid[i][j]
                break
        if marker:
            break

    # Determine fill color based on marker
    if marker == 8:
        fill = 2
    elif marker == 5:
        fill = 4
    elif marker == 3:
        fill = 1
    else:
        fill = marker  # default for unknown

    # Build output
    out = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r, c in positions:
        out[r][c] = 0  # markers become 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i, j) not in positions:
                out[i][j] = fill  # rest becomes fill
    return out

